"""Bind a reviewed bridge packet to original source bytes before live construction."""
from __future__ import annotations

import hashlib
from pathlib import Path

REQUIRED = {"map", "highway", "centerline", "lane_forward", "ego_vehicle",
            "bridge", "bridge_entrance", "view_geometry", "camera_plan"}


def bind(packet, root):
    root = Path(root).resolve()
    entries = packet.get("sources")
    if not isinstance(entries, list):
        raise ValueError("reviewed original source inventory missing")
    roles = [item.get("role") for item in entries if isinstance(item, dict)]
    if len(roles) != len(set(roles)) or not REQUIRED <= set(roles):
        raise ValueError("reviewed bridge source roles missing or duplicated")
    if not packet["road"]["one_way_highway"] and "lane_reverse" not in roles:
        raise ValueError("opposite-direction lane source missing")
    if packet.get("opaque_blocker") and "opaque_blocker" not in roles:
        raise ValueError("opaque blocker source missing")
    bound = {}
    for item in entries:
        if not isinstance(item, dict) or not item.get("path") or not item.get("sha256"):
            raise ValueError("unversioned reviewed source entry")
        path = root / item["path"]
        if path.is_symlink() or not path.is_file() or not path.resolve().is_relative_to(root):
            raise ValueError("reviewed original source path missing or escapes root")
        actual = hashlib.sha256(path.read_bytes()).hexdigest()
        if actual != item["sha256"]:
            raise ValueError("reviewed original source bytes changed")
        bound[item["role"]] = {"path": str(path), "sha256": actual}
    if bound["map"]["sha256"] != packet.get("map_opendrive_sha256"):
        raise ValueError("reviewed map differs from Native setup")
    road = packet["road"]
    for role, key in (("centerline", "centerline_source_sha256"),
                      ("bridge", "bridge_source_sha256")):
        if bound[role]["sha256"] != road.get(key):
            raise ValueError("reviewed " + role + " differs from Native setup")
    return bound

"""Saved-only bridge approach finalizer over original Native sources."""
from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path

from bridge_measure import measure

SOURCES = ("bridge-history.jsonl", "road-context.json", "native-result.json",
           "video_frames.jsonl", "reviewed-sources/map.source",
           "reviewed-sources/centerline.source", "reviewed-sources/bridge.source")


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def required(root, name):
    path = Path(root) / name
    if not path.is_file():
        raise ValueError("Missing required source: " + name)
    return path


def rows(path):
    return [json.loads(line) for line in Path(path).read_text().splitlines() if line.strip()]



def measure_vehicle_driver(measured):
    return {"ego_vehicle": True, "original_frames": len(measured["per_frame"])}


def measure_bridge_context(measured):
    return {"structure_type": "bridge", "bridge_entrance_station_m": measured["bridge_entrance_station_m"]}


def measure_left_side(measured):
    return {"left_body_edge_m": [row["left_body_edge_m"] for row in measured["per_frame"]],
            "body_crossing": [row["left_of_center_body"] for row in measured["per_frame"]]}


def measure_approach_distance(measured):
    return {"statutory_distance_m": measured["statutory_distance_m"],
            "front_center_rear_m": [[row["bridge_distance_front_m"], row["bridge_distance_center_m"], row["bridge_distance_rear_m"]] for row in measured["per_frame"]],
            "reference_unresolved": measured["distance_reference_unresolved"]}


def measure_view(measured):
    return {"ray_brackets": [row["ray_brackets"] for row in measured["per_frame"]],
            "view_obstructed_judgment": measured["view_obstructed_judgment"]}


def measure_one_way(measured):
    return {"one_way_highway": measured["one_way_highway"]}


METHODS = (measure_vehicle_driver, measure_bridge_context, measure_left_side,
           measure_approach_distance, measure_view, measure_one_way)

def analyze(root):
    root = Path(root)
    for name in SOURCES:
        required(root, name)
    history = rows(root / "bridge-history.jsonl")
    mapping = rows(root / "video_frames.jsonl")
    if not history or len(history) != len(mapping):
        raise ValueError("original bridge history/frame-map join incomplete")
    for index, (body, frame) in enumerate(zip(history, mapping)):
        if body.get("original_frame") != index or body.get("carla_frame") != frame.get("carla_frame") or abs(body.get("time_s", -1)-frame.get("time_s", -2)) > 1e-6:
            raise ValueError("original bridge frame-map identity mismatch")
    road = json.loads((root / "road-context.json").read_text())
    native = json.loads((root / "native-result.json").read_text())
    config = json.loads(required(root, "config.json").read_text())
    if native.get("recording_description") != config.get("case", {}).get("recording_description"):
        raise ValueError("original recording description differs from selected case")
    fixture = root / "fixture-provenance.json"
    is_fixture = fixture.is_file() and json.loads(fixture.read_text()).get("diagnostic_fixture") is True
    if not is_fixture and len(history) != config.get("duration_s", len(history))*20:
        raise ValueError("original bridge episode duration incomplete")
    hashes = {name: sha(root / name) for name in SOURCES}
    if road.get("centerline_source_sha256") != hashes["reviewed-sources/centerline.source"]:
        raise ValueError("original centerline source changed")
    if road.get("bridge_source_sha256") != hashes["reviewed-sources/bridge.source"]:
        raise ValueError("original bridge source changed")
    measured = measure({"road": road, "frames": history})
    measurements = {method.__name__: {"value": method(measured), "method": method.__name__,
                                      "sources": hashes} for method in METHODS}
    measurements["measure_bridge_approach"] = {"value": measured, "method": "measure_bridge_approach", "sources": hashes}
    report = {"format": "worker-analysis-report", "case_id": config["selected_case_id"],
              "measurements": measurements, "analysis_complete": True,
              "physical_acceptance_claimed": False,
              "limitations": ["Original pixels and actual obstruction require independent review.",
                              "Distance reference and view-obstruction judgment remain unresolved."]}
    return report, native


def channel_value(name, row, road):
    ego = row["actors"]["ego"]
    if name == "bridge_identity_and_entrance":
        return {key: road[key] for key in ("structure_type", "bridge_entrance_station_m", "bridge_source_sha256")}
    if name == "highway_directionality":
        return {key: road[key] for key in ("public_highway", "one_way_highway", "lanes")}
    if name == "vehicle_body_and_centerline":
        return {"ego": ego, "centerline_source_sha256": road["centerline_source_sha256"]}
    if name == "approach_progression":
        return {"station_m": ego["station_m"], "front_station_m": ego["front_station_m"]}
    if name == "bridge_distance_front_center_rear":
        entrance = road["bridge_entrance_station_m"]
        return {"front_m": entrance-ego["front_station_m"],
                "center_m": entrance-ego["station_m"],
                "rear_m": entrance-ego["rear_station_m"]}
    if name == "left_side_body_occupancy":
        return {"left_body_edge_m": ego["centerline_signed_body_edge_m"],
                "body_vertices_xy_m": ego["body_vertices_xy_m"]}
    if name == "view_ray_brackets":
        return row["left_side_rays"]
    if name == "original_frame_and_camera_join":
        return {"original_frame": row["original_frame"], "carla_frame": row["carla_frame"]}
    raise ValueError("unknown selected bridge channel: " + name)


def write_channels(root, description):
    root = Path(root)
    history = rows(root / "bridge-history.jsonl")
    road = json.loads((root / "road-context.json").read_text())
    folder = root / "channels"
    folder.mkdir(exist_ok=True)
    evidence = []
    for channel in description["channels"]:
        name = channel["name"]
        path = folder / (name + ".jsonl")
        if path.exists():
            raise ValueError("derived channel already exists")
        with path.open("x") as stream:
            for row in history:
                stream.write(json.dumps({"time_s": row["time_s"],
                                         "value": channel_value(name, row, road)},
                                        allow_nan=False) + "\n")
        evidence.append({"name": name, "unit": channel["unit"],
                         "reference": str(path.relative_to(root)),
                         "source_sha256": sha(path)})
    return evidence


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--attempt", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    report, native = analyze(args.attempt)
    from worker_exchange.native_output import physical_result, validate_result
    native["case_id"] = report["case_id"]
    native["measured_values"].update({key: item["value"] for key, item in report["measurements"].items()})
    native["recording_evidence"] = write_channels(args.attempt, native["recording_description"])
    native = physical_result(args.attempt, native)
    validate_result(native)
    (args.attempt / "result.json").write_text(json.dumps(native, indent=2) + "\n")
    args.output.write_text(json.dumps(report, indent=2) + "\n")


if __name__ == "__main__":
    main()

"""Independent original-source delivery audit for one exact bridge approach.

A diagnostic protocol check verifies software joins only. Native acceptance requires
separate original pixel and physical review; no legal judgment is produced.
"""
from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path

from native_scene import ASSIGNMENT, CASE_VARIANTS, CAMERAS


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def read(path):
    return json.loads(Path(path).read_text())


def rows(path):
    return [json.loads(line) for line in Path(path).read_text().splitlines() if line.strip()]


def audit(attempt, case_id, output, *, diagnostic_protocol=False):
    from worker_exchange.media import audit as decode
    attempt, output = Path(attempt).resolve(), Path(output).resolve()
    if output.exists():
        raise ValueError("retain prior delivery audit output")
    if not case_id.startswith(ASSIGNMENT + "__") or case_id.removeprefix(ASSIGNMENT + "__") not in CASE_VARIANTS:
        raise ValueError("exact delivery case mismatch")
    required = ("bridge-history.jsonl", "video_frames.jsonl", "trace.jsonl",
                "road-context.json", "native-result.json", "analysis-report.json", "result.json")
    for name in required:
        if not (attempt / name).is_file():
            raise ValueError("missing original delivery evidence: " + name)
    provenance = read(attempt / "acquisition-provenance.json")
    is_fixture = provenance.get("diagnostic_fixture") is True
    if diagnostic_protocol:
        if not is_fixture:
            raise ValueError("diagnostic protocol requires explicit synthetic provenance")
    elif is_fixture:
        raise ValueError("synthetic fixture cannot be accepted as Native delivery")
    else:
        seal = read(attempt / "capture-seal.json")
        if seal.get("events") != ["capture_finished", "encoders_closed", "restoration_verified"]:
            raise ValueError("Native closure order missing")
        for name, expected in seal.get("sources", {}).items():
            if sha(attempt / name) != expected:
                raise ValueError("sealed original source changed: " + name)
        native_exit = read(attempt / "native-exit.json")
        if native_exit.get("capture_seal_sha256") != sha(attempt / "capture-seal.json"):
            raise ValueError("Native exit source binding changed")
        owner = read(attempt / "owner-release-attested.json")
        if owner.get("event") != "owner_released" or owner.get("operator_attested") is not True:
            raise ValueError("operator owner release missing")
    history = rows(attempt / "bridge-history.jsonl")
    mapping = rows(attempt / "video_frames.jsonl")
    trace = rows(attempt / "trace.jsonl")
    if not history or len(history) != len(mapping) or len(history) != len(trace):
        raise ValueError("original body/trace/frame count mismatch")
    for index, (body, frame, point) in enumerate(zip(history, mapping, trace)):
        if body.get("original_frame") != index or body.get("carla_frame") != frame.get("carla_frame") or point.get("frame") != frame.get("carla_frame") or abs(body.get("time_s", -1)-frame.get("time_s", -2)) > 1e-6:
            raise ValueError("original time join mismatch")
        if "ego" not in body.get("actors", {}):
            raise ValueError("required bridge participant absent")
    report = read(attempt / "analysis-report.json")
    result = read(attempt / "result.json")
    if report.get("case_id") != case_id or result.get("case_id") != case_id or not report.get("analysis_complete"):
        raise ValueError("saved analysis identity or completion missing")
    for value in report.get("measurements", {}).values():
        for name, expected in value.get("sources", {}).items():
            if sha(attempt / name) != expected:
                raise ValueError("source-bound measurement changed: " + name)
    measured = report["measurements"]["measure_bridge_approach"]["value"]
    if measured.get("one_way_highway") != case_id.endswith("one_way_exception"):
        raise ValueError("measured one-way status differs from exact case")
    samples = measured.get("per_frame", [])
    if not samples or not any(s["bridge_distance_front_m"] >= 0 for s in samples):
        raise ValueError("bridge approach body history missing")
    if case_id.endswith("right_side_within_100ft"):
        if any(s["left_of_center_body"] for s in samples):
            raise ValueError("right-side reference crossed centerline")
    elif not any(s["left_of_center_body"] for s in samples):
        raise ValueError("left-of-center bridge approach never measured")
    if not diagnostic_protocol:
        physical = result.get("physical_checks", {})
        if physical.get("setup", {}).get("status") != "met" or physical.get("attempt", {}).get("status") != "met":
            raise ValueError("original physical setup or motion unconfirmed")
    decoded = {}
    output.parent.mkdir(parents=True, exist_ok=True)
    for name in CAMERAS:
        video = attempt / (name + ".mkv")
        if not video.is_file():
            raise ValueError("original camera missing: " + name)
        receipt = output.with_name(output.stem + "-decode-" + name + ".json")
        decoded[name] = decode(video, len(mapping), mapping_sha256=sha(attempt / "video_frames.jsonl"), receipt=receipt)
    if not diagnostic_protocol:
        pixel = read(attempt / "pixel-review.json")
        if pixel.get("case_id") != case_id or pixel.get("reviewer") in (None, "") or pixel.get("actual_pixels_visible") is not True or pixel.get("physical_completion_reviewed") is not True:
            raise ValueError("independent actual-pixel and physical review missing")
        if pixel.get("video_sha256") != {name:sha(attempt / (name + ".mkv")) for name in CAMERAS}:
            raise ValueError("pixel review references different original footage")
    audit_record = {"format":"worker-delivery-audit-diagnostic" if diagnostic_protocol else "worker-delivery-audit",
                    "case_id":case_id,"original_frames":len(mapping),
                    "original_source_sha256":{name:sha(attempt / name) for name in required},
                    "decoded_video_sha256":{name:item["video_sha256"] for name,item in decoded.items()},
                    "checks":["native_source","all_participants","time_join","full_video_decode",
                              "actual_pixels","physical_completion"],
                    "actual_pixels_reviewed":not diagnostic_protocol,
                    "physical_acceptance_claimed":False,"legal_judgment":"unresolved"}
    output.write_text(json.dumps(audit_record, indent=2) + "\n")
    return audit_record


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--attempt", type=Path, required=True)
    parser.add_argument("--case", required=True)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--diagnostic-protocol", action="store_true")
    args = parser.parse_args()
    result = audit(args.attempt,args.case,args.output,diagnostic_protocol=args.diagnostic_protocol)
    print(json.dumps({"case_id":result["case_id"],"frames":result["original_frames"],
                      "physical_acceptance_claimed":False},sort_keys=True))


if __name__ == "__main__":main()

"""Independent saved-only, source-bound bridge comparison audit."""
from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path

FACTORS = {
    "distance_beyond_at": "bridge_distance_front_m",
    "distance_at_within": "bridge_distance_front_m",
    "view_obstructed_clear": "ray_brackets",
    "left_side_right_side": "left_body_edge_m",
    "one_way_exception": "one_way_highway",
}


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def read(path):
    return json.loads(Path(path).read_text())


def source_report(folder, case_id, diagnostic):
    folder = Path(folder).resolve()
    provenance = read(folder / "acquisition-provenance.json")
    if diagnostic:
        if provenance.get("diagnostic_fixture") is not True:
            raise ValueError("positive CPU comparison requires explicit diagnostic fixture")
    elif provenance.get("diagnostic_fixture") is True:
        raise ValueError("synthetic fixture cannot establish Native comparison")
    report = read(folder / "analysis-report.json")
    if report.get("case_id") != case_id or report.get("analysis_complete") is not True:
        raise ValueError("saved analysis case identity or completeness differs")
    for name, expected in report["measurements"]["measure_bridge_approach"]["sources"].items():
        if sha(folder / name) != expected:
            raise ValueError("saved original source changed: " + name)
    if not diagnostic:
        pixel = read(folder / "pixel-review.json")
        if pixel.get("case_id") != case_id or pixel.get("actual_pixels_visible") is not True:
            raise ValueError("independent actual pixel review missing")
        result = read(folder / "result.json")
        if result.get("physical_checks", {}).get("attempt", {}).get("status") != "met":
            raise ValueError("Native physical completion unconfirmed")
    return report["measurements"]["measure_bridge_approach"]["value"]


def audit(plan_path, left_path, right_path, comparison_id, diagnostic=False):
    plan = read(plan_path)
    comparison = next((row for row in plan["comparisons"] if row["comparison_id"] == comparison_id), None)
    if comparison is None or comparison_id not in FACTORS:
        raise ValueError("unknown exact bridge comparison")
    left, right = (source_report(path, case, diagnostic) for path, case in
                   zip((left_path, right_path), comparison["case_ids"]))
    source_names = ("map.source", "centerline.source", "bridge.source")
    for name in source_names:
        if comparison_id != "one_way_exception" and sha(Path(left_path) / "reviewed-sources" / name) != sha(Path(right_path) / "reviewed-sources" / name):
            raise ValueError("reviewed fixed source differs: " + name)
    lc, rc = (read(Path(path) / "config.json") for path in (left_path, right_path))
    for key in ("law_id", "cell_id", "actor", "rate_hz", "duration_s", "cameras"):
        if lc.get(key) != rc.get(key):
            raise ValueError("shared construction contract differs: " + key)
    if left["bridge_entrance_station_m"] != right["bridge_entrance_station_m"]:
        raise ValueError("bridge entrance reference differs")
    if comparison_id != "one_way_exception" and left["one_way_highway"] != right["one_way_highway"]:
        raise ValueError("uncontrolled one-way status differs")
    a, b = left["per_frame"], right["per_frame"]
    if not a or not b or len(a) != len(b):
        raise ValueError("original comparison frame history differs")
    factor = FACTORS[comparison_id]
    if factor == "one_way_highway":
        changed = left[factor] != right[factor]
    else:
        changed = any(x[factor] != y[factor] for x, y in zip(a, b))
    if not changed:
        raise ValueError("declared bridge factor has no measured difference")
    for x, y in zip(a, b):
        if x["original_frame"] != y["original_frame"]:
            raise ValueError("original frame alignment differs")
        for field in ("bridge_distance_front_m", "left_body_edge_m", "ray_brackets"):
            if field == factor or (comparison_id == "one_way_exception" and field == "ray_brackets"):
                continue
            if x[field] != y[field]:
                raise ValueError("uncontrolled measured condition differs: " + field)
    return {"format": "worker-source-bound-comparison-audit-diagnostic" if diagnostic else "worker-source-bound-comparison-audit",
            "comparison_id": comparison_id, "case_ids": comparison["case_ids"],
            "factor_measurement": factor, "left_report_sha256": sha(Path(left_path) / "analysis-report.json"),
            "right_report_sha256": sha(Path(right_path) / "analysis-report.json"),
            "legal_judgment": "unresolved", "physical_acceptance_claimed": False}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--plan", type=Path, required=True)
    parser.add_argument("--left-attempt", type=Path, required=True)
    parser.add_argument("--right-attempt", type=Path, required=True)
    parser.add_argument("--comparison", required=True)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--diagnostic-protocol", action="store_true")
    args = parser.parse_args()
    result = audit(args.plan, args.left_attempt, args.right_attempt, args.comparison, args.diagnostic_protocol)
    if args.output.exists():
        raise ValueError("retain prior comparison audit output")
    args.output.write_text(json.dumps(result, indent=2) + "\n")
    print(result["comparison_id"])


if __name__ == "__main__":
    main()
